using System;using System.Data;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using QuanLyNhanSu.Services;
namespace QuanLyNhanSu.Forms {
 public class BusinessForm:Form {
  protected readonly NhanSuService svc=new NhanSuService(); protected readonly Dictionary<string,Control> inputs=new Dictionary<string,Control>();
  protected FlowLayoutPanel fields,actions;protected DataGridView grid,details;protected ComboBox table;protected Label status;
  protected void LayoutForm(string title,string[] tables){Text=title;ClientSize=new Size(1120,740);MinimumSize=new Size(1000,700);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(244,246,249);
   var header=new Label{Text=title,Font=new Font("Segoe UI",19,FontStyle.Bold),ForeColor=Color.FromArgb(25,66,105),Dock=DockStyle.Top,Height=58,Padding=new Padding(18,12,0,0)};
   fields=new FlowLayoutPanel{Dock=DockStyle.Top,Height=280,AutoScroll=true,Padding=new Padding(12),WrapContents=true}; actions=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50,Padding=new Padding(12,4,0,0)};
   var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=44,Padding=new Padding(12,4,0,0)};bar.Controls.Add(new Label{Text="Dữ liệu đang xem",Width=140,Padding=new Padding(0,5,0,0)});table=new ComboBox{Width=220,DropDownStyle=ComboBoxStyle.DropDownList};table.Items.AddRange(tables);table.SelectedIndex=0;bar.Controls.Add(table);var refresh=new Button{Text="Tải lại",Width=100};refresh.Click+=(s,e)=>Run(()=>ShowTable());bar.Controls.Add(refresh);
   grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,BackgroundColor=Color.White,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect};status=new Label{Dock=DockStyle.Bottom,Height=38,Padding=new Padding(12,8,0,0),Text="Sẵn sàng. Mã bộ phận: PB01 nhân sự, PB02 kế toán, PB04 chấm công, PB05 giám đốc."};
   Controls.Add(grid);Controls.Add(bar);Controls.Add(actions);Controls.Add(fields);Controls.Add(header);Controls.Add(status);Shown+=(s,e)=>Run(()=>ShowTable());
  }
  protected void Input(string key,string label,string initial,string options=null){var box=new Panel{Width=350,Height=58};box.Controls.Add(new Label{Text=label,Location=new Point(0,0),Width=340,Height=22});Control c;if(options!=null){var cb=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};cb.Items.AddRange(options.Split('|'));cb.SelectedItem=initial;c=cb;}else c=new TextBox{Text=initial};c.Location=new Point(0,24);c.Size=new Size(330,27);box.Controls.Add(c);inputs.Add(key,c);fields.Controls.Add(box);}
  protected void DateInput(string key,string label,DateTime date){var box=new Panel{Width=350,Height=58};box.Controls.Add(new Label{Text=label,Width=340,Height=22});var c=new DateTimePicker{Format=DateTimePickerFormat.Custom,CustomFormat="dd/MM/yyyy",Value=date,Location=new Point(0,24),Size=new Size(330,27)};box.Controls.Add(c);inputs.Add(key,c);fields.Controls.Add(box);}
  protected void Button(string label,Action action){var b=new Button{Text=label,AutoSize=true,Height=34,BackColor=Color.White,Padding=new Padding(9,0,9,0)};b.Click+=(s,e)=>Run(()=>{action();status.Text="Thành công: "+label;});actions.Controls.Add(b);}
  protected void AddDetails(params string[] cols){details=new DataGridView{Dock=DockStyle.Top,Height=142,AllowUserToAddRows=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White};foreach(var c in cols)details.Columns.Add(c,c);Controls.Add(details);Controls.SetChildIndex(details,1);}
  protected string S(string k){return inputs[k].Text.Trim();}protected decimal N(string k){decimal v;if(!decimal.TryParse(S(k),out v))throw new Exception("Số không hợp lệ: "+k);return v;}protected DateTime D(string k){return ((DateTimePicker)inputs[k]).Value.Date;}
  protected void ShowTable(){grid.DataSource=svc.Xem(Convert.ToString(table.SelectedItem));foreach(DataGridViewColumn c in grid.Columns){if(c.ValueType==typeof(DateTime))c.DefaultCellStyle.Format="dd/MM/yyyy";if(c.ValueType==typeof(decimal))c.DefaultCellStyle.Format="N0";}}
  protected void Run(Action action){try{action();}catch(Exception ex){string message=ex.Message;var sql=ex as System.Data.SqlClient.SqlException;if(sql!=null){if(sql.Number==2627||sql.Number==2601)message="Mã hoặc chứng từ đã tồn tại. Kiểm tra danh sách và dùng mã khác.";else if(sql.Number==547)message="Liên kết hoặc giá trị không hợp lệ. Kiểm tra mã tham chiếu và giới hạn dữ liệu.";else if(sql.Number==-2)message="Kết nối hoặc truy vấn quá thời gian chờ. Kiểm tra máy chủ SQL Server.";}status.Text="Chưa thực hiện: "+message;MessageBox.Show(this,message,"Kiểm tra dữ liệu",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 }
}
